import re,time
t=str(int(time.time()))
for page,mf in [('pdf.html','editor-s1.main.html')]:
    s=open(page,encoding='utf-8').read(); m=open(mf,encoding='utf-8').read()
    s=re.sub(r'<main.*?</main>',lambda x:m,s,count=1,flags=re.S); open(page,'w',encoding='utf-8').write(s)
for p in ['pdf.html','assistant.html','money.html','finance.html','voice.html','chat.html','atlas.html']:
    s=open(p,encoding='utf-8').read(); s=re.sub(r'nox-ds-s1\.css\?v=[0-9]*','nox-ds-s1.css?v='+t,s); open(p,'w',encoding='utf-8').write(s)
print('p1 ok')
P
